FUNCTION_BLOCK FB_LoopCounter
VAR_INPUT
    i : BOOL;  // Trigger input for the counter
END_VAR

VAR
    macro : INT := 1;  // Current count
    micro : INT := 1;  // Control variable for counting down
END_VAR

VAR_OUTPUT
    o : INT;  // Current value of the counter
END_VAR

// Main execution logic
IF i THEN
    // Check if micro is greater than 0
    IF micro > 0 THEN
        // Decrement micro
        micro := micro - 1;
    END_IF;

    // Check if micro has reached zero
    IF micro = 0 THEN
        // Increment macro
        macro := macro + 1;
        // Reset micro to the new value of macro
        micro := macro;
    END_IF;
END_IF;

// Ensure output is always a positive integer
o := macro;

END_FUNCTION_BLOCK
